using UnityEngine;using System.Collections;
public static class MedicalLeverMotion {
 static float Ease(float t,float a,float b)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,t));
 static void Hand(Transform arm,Vector3 contact,Quaternion rotation){arm.rotation=rotation;var rs=arm.GetComponentsInChildren<Renderer>();foreach(var r in rs)if(r.name=="Inspection glove"){arm.position+=contact-r.bounds.center;break;}}
 static Transform Sleeve(Transform arm){foreach(var r in arm.GetComponentsInChildren<Renderer>())if(r.name=="olive sleeve"){var g=GameObject.CreatePrimitive(PrimitiveType.Capsule);Object.Destroy(g.GetComponent<Collider>());g.name="Crowbar sleeve extension";g.GetComponent<Renderer>().sharedMaterial=r.sharedMaterial;g.transform.SetParent(arm,true);return g.transform;}return null;}
 static void Connect(Transform arm,Transform ext,Camera eye,bool right){if(!ext)return;foreach(var r in arm.GetComponentsInChildren<Renderer>())if(r.name=="olive sleeve"){Vector3 a=r.bounds.center,b=eye.transform.TransformPoint(new Vector3(right?.38f:-.38f,-.5f,.02f));ext.SetParent(null,true);ext.position=(a+b)*.5f;ext.rotation=Quaternion.FromToRotation(Vector3.up,a-b);ext.localScale=new Vector3(.105f,Vector3.Distance(a,b)*.5f,.105f);break;}}
 public static IEnumerator Play(MedicalInterior scene){var p=scene.owner.player;var bar=scene.crowbar;var left=Object.Instantiate(p.nodeRepair.repairArm,p.eye.transform);var right=Object.Instantiate(p.nodeRepair.rightArm,p.eye.transform);left.name="Crowbar supporting arm";right.name="Crowbar pulling arm";left.localScale*=.68f;right.localScale*=.68f;left.gameObject.SetActive(true);right.gameObject.SetActive(true);var le=Sleeve(left);var re=Sleeve(right);bar.SetParent(scene.transform,true);bar.gameObject.SetActive(true);var contactMarker=scene.jammedDoor.Find("Crowbar contact");var contact=contactMarker?contactMarker.position:scene.jammedDoor.TransformPoint(new Vector3(2.08f,1.04f,-.14f));var start=p.eye.transform.TransformPoint(new Vector3(.28f,-.35f,.55f));var look=Quaternion.LookRotation(contact-p.eye.transform.position);var cameraRest=p.eye.transform.rotation;scene.atmosphere.PlayOneShot(scene.force,.6f);
 for(float t=0;t<4.6f&&!p.anatomy.Incapacitated;t+=Time.deltaTime){float insert=Ease(t,.2f,1.1f),pull=Ease(t,1.45f,2.8f),withdraw=Ease(t,3.65f,4.6f);float angle=Mathf.Lerp(-18,27,pull);bar.rotation=Quaternion.Euler(0,p.transform.eulerAngles.y,angle);Vector3 tip=Vector3.Lerp(start,contact,insert);tip=Vector3.Lerp(tip,start-Vector3.up*.4f,withdraw);bar.position=tip-bar.up*.31f;p.eye.transform.rotation=Quaternion.Slerp(cameraRest,look,insert*(1-withdraw)*.8f);Hand(left,bar.position+bar.up*.07f,p.eye.transform.rotation*Quaternion.Euler(15,180,30));Hand(right,bar.position-bar.up*.17f,p.eye.transform.rotation*Quaternion.Euler(15,180,-30));Connect(left,le,p.eye,false);Connect(right,re,p.eye,true);scene.jammedDoor.localRotation=Quaternion.Euler(0,-105*Ease(t,2.8f,3.6f),0);yield return null;}
 p.eye.transform.rotation=cameraRest;if(le)Object.Destroy(le.gameObject);if(re)Object.Destroy(re.gameObject);Object.Destroy(left.gameObject);Object.Destroy(right.gameObject);bar.gameObject.SetActive(false);
 }
}
